import { requireCompanyAuth, jsonError } from "../_shared/auth.ts";
import { corsHeaders } from "../_shared/cors.ts";

// Pairs a physical phone to a CRM user so the Power Dialer can hand off
// call requests to it. A pairing token is a short-lived, single-use secret
// (hashed at rest) generated by the desktop side and consumed by the phone
// side once, over an authenticated request from the SAME logged-in user —
// this is not a bearer-token-only scheme, both sides must be the same
// authenticated account.

const PAIRING_TOKEN_TTL_MINUTES = 10;

function generateToken(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(24));
  return Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function hashToken(token: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
  return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const ctx = await requireCompanyAuth(req);
  if (ctx instanceof Response) return ctx;
  const { supabase, user, companyId } = ctx;

  let body: Record<string, unknown> = {};
  try {
    body = await req.json();
  } catch {
    // no body
  }
  const action = body.action as string | undefined;

  try {
    // ─── Desktop: start a new pairing, invalidating any older unclaimed one ───
    if (action === "create-pairing-token") {
      const { data: verifiedIdentity } = await supabase
        .from("phone_identities")
        .select("id, phone_number")
        .eq("company_id", companyId)
        .eq("user_id", user.id)
        .eq("verification_status", "verified")
        .order("verified_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (!verifiedIdentity) {
        throw new Error("Bekræft dit telefonnummer først, før du forbinder en telefon.");
      }

      // Clear out any stale pending pairing for this user (the unique
      // index only allows one 'pending' row per user at a time).
      await supabase
        .from("mobile_devices")
        .delete()
        .eq("company_id", companyId)
        .eq("user_id", user.id)
        .eq("pairing_status", "pending");

      const token = generateToken();
      const tokenHash = await hashToken(token);
      const expiresAt = new Date(Date.now() + PAIRING_TOKEN_TTL_MINUTES * 60_000).toISOString();

      const { data: device, error } = await supabase
        .from("mobile_devices")
        .insert({
          company_id: companyId,
          user_id: user.id,
          phone_identity_id: verifiedIdentity.id,
          device_name: "Min telefon",
          pairing_token_hash: tokenHash,
          pairing_token_expires_at: expiresAt,
          pairing_status: "pending",
        })
        .select("id")
        .single();
      if (error) throw new Error(error.message);

      return jsonResponse({ deviceId: device.id, token, expiresAt });
    }

    // ─── Phone: consume the token, completing the pairing ───
    if (action === "pair") {
      const token = body.token as string;
      if (!token) throw new Error("Missing token");
      const tokenHash = await hashToken(token);

      const { data: device, error } = await supabase
        .from("mobile_devices")
        .select("id, user_id, pairing_status, pairing_token_expires_at, phone_identity_id")
        .eq("company_id", companyId)
        .eq("pairing_token_hash", tokenHash)
        .maybeSingle();
      if (error || !device) throw new Error("Ugyldigt eller allerede brugt link.");
      if (device.user_id !== user.id) throw new Error("Dette link tilhører en anden bruger.");
      if (device.pairing_status !== "pending") throw new Error("Dette link er allerede brugt.");
      if (!device.pairing_token_expires_at || new Date(device.pairing_token_expires_at) < new Date()) {
        await supabase.from("mobile_devices").update({ pairing_status: "expired" }).eq("id", device.id);
        throw new Error("Linket er udløbet. Generér et nyt fra computeren.");
      }

      const { data: phoneIdentity } = await supabase
        .from("phone_identities")
        .select("phone_number")
        .eq("id", device.phone_identity_id)
        .maybeSingle();

      const { error: updateError } = await supabase
        .from("mobile_devices")
        .update({
          pairing_status: "paired",
          paired_at: new Date().toISOString(),
          last_seen_at: new Date().toISOString(),
          pairing_token_hash: null,
          pairing_token_expires_at: null,
        })
        .eq("id", device.id);
      if (updateError) throw new Error(updateError.message);

      await supabase.from("profiles").update({ active_mobile_device_id: device.id }).eq("user_id", user.id);

      return jsonResponse({ deviceId: device.id, phoneNumber: phoneIdentity?.phone_number ?? null, status: "paired" });
    }

    if (action === "list") {
      const { data, error } = await supabase
        .from("mobile_devices")
        .select("id, device_name, pairing_status, paired_at, last_seen_at, created_at")
        .eq("company_id", companyId)
        .eq("user_id", user.id)
        .neq("pairing_status", "expired")
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return jsonResponse({ devices: data ?? [] });
    }

    if (action === "heartbeat") {
      const deviceId = body.deviceId as string;
      if (!deviceId) throw new Error("Missing deviceId");
      const { error } = await supabase
        .from("mobile_devices")
        .update({ last_seen_at: new Date().toISOString() })
        .eq("id", deviceId)
        .eq("company_id", companyId)
        .eq("user_id", user.id)
        .eq("pairing_status", "paired");
      if (error) throw new Error(error.message);
      return jsonResponse({ success: true });
    }

    if (action === "revoke") {
      const deviceId = body.deviceId as string;
      if (!deviceId) throw new Error("Missing deviceId");
      const { error } = await supabase
        .from("mobile_devices")
        .update({ pairing_status: "revoked", revoked_at: new Date().toISOString() })
        .eq("id", deviceId)
        .eq("company_id", companyId)
        .eq("user_id", user.id);
      if (error) throw new Error(error.message);

      // Clear active_mobile_device_id if this was the active device.
      await supabase
        .from("profiles")
        .update({ active_mobile_device_id: null })
        .eq("user_id", user.id)
        .eq("active_mobile_device_id", deviceId);

      return jsonResponse({ success: true });
    }

    throw new Error(`Unknown action: ${action}`);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return jsonError(message, 400);
  }
});

function jsonResponse(data: unknown) {
  return new Response(JSON.stringify(data), {
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}
